	(105, 'LI-0520-0019', 'Meeting Investigasi Bersama, dengan action plant : Simulasi IS-43, Function test Gov TS-0431, Pengecekan limit switch PALL LO & TTV Trip', 'Plant', 'refer ke laporan terlampir', 'refer ke laporan terlampir', 'pada 17 mei 2020 17:05 (waktu dcs), muncul alarm za04402: k-0431 exerciser, dan ts/k-0431 tripkemudian oleh karena ts/k-0431 trip, steam system terjadi goncangan sehingga steam/gas ratio turun menyentuh setting low-low, dan plant trip (is-21).pressure sh over sehingga popping di psv-0205 a/b', NULL, 'Close', '2020-05-17 14:00:38', '2020-06-08 10:00:00', '2020-07-28 15:07:17', '2020-05-18 07:40:03', '2020-05-20 08:34:52', NULL, 393609, 432969.90, '2020-05-16 09:24:26', '2021-03-07 22:34:57', NULL, 150, 96, 4, 4, 2, 4, 8, 6, 168, 63, NULL, 2, 1, 1),
	(106, 'LI-0520-0020', 'Meeting Investigasi bersama, Pengecekan oleh Elektrik', 'MCC', 'Tidak ada, karena berdasarkan data dari Digital Fault Recorder, memang kejadian tersebut adalah benar dan relay sudah bekerja sesuai dengan settingnya.', 'Tidak ada', 'pada 17 mei 20 14:01:37 (waktu dcs) kdm open breakerpengecekan awal, ada indikasi reverse power stg kpi', NULL, 'Close', '2020-05-17 17:01:37', '2020-05-18 13:47:18', '2020-05-26 14:56:01', '2020-05-20 08:44:43', '2020-05-26 10:29:09', NULL, NULL, NULL, '2020-05-16 09:28:57', '2020-07-01 05:48:31', NULL, 150, 96, 4, 4, 2, 3, 3, 6, 168, 83, NULL, 2, 1, 2),
	(107, 'LI-0520-0021', 'Shut Down HARU, pengamanan system, wr23886', 'HARU', 'Penggantian flange dan pipe upstream LV-08002', 'Pengecekan visual, PT dan thickness piping upstream dan downstream LV-08002 (shutdown item)', '-pada 09:53 muncul alarm low level lv08002 (c-0801 hp scrubber) di dcs-kemudian operator berusaha melakukan action menormalkan kondisi operasi (memanualkan lv08002 dan berusaha menaikkan level c-0801), sambil field operator melakukan pengecekan di lapangan-dari pengecekan operator di lapangan ditemukan bocoran yang besar, pada upstream lv-08002-karena kondisi yang tidak memungkinkan untuk dipertahankan, unit haru kemudian di shut downkan dan diamankan untuk perbaikan lebih lanjut', NULL, 'Close', '2020-05-22 09:53:00', '2020-06-10 00:00:00', '2020-07-28 15:06:45', '2020-05-22 11:59:32', '2020-05-26 10:28:25', NULL, 169, 760.50, '2020-05-21 03:50:28', '2021-03-07 22:48:41', NULL, 150, 96, 4, 4, 2, 3, 8, 6, 168, 56, NULL, 1, 1, 1),
	(108, 'LI-0520-0022', 'WR23902', 'V-0251', 'Dilakukan perbaikan secara temporary dengan center pen dan kemudian dilakukan pengelasan pada area yang crack. PT OK.', 'Pada TA2021, direncanakan akan dilakukan perbaikan secara permanent sesuai Technical Recommendation No. 197/Rec-INS/TSP/X/2020.', 'body deaerator leak out', NULL, 'Close', '2020-05-28 19:30:00', '2020-05-29 10:47:58', '2020-07-28 14:46:30', '2020-06-08 09:58:41', '2020-06-08 10:59:55', NULL, 233, 1048.50, '2020-05-28 07:09:55', '2021-03-07 22:46:54', NULL, 150, 96, 4, 4, 2, 2, 8, 6, 168, 61, NULL, 1, 1, 1),
	(109, 'LI-0520-0023', 'WR23895', 'PV-1103', 'Perbaikan akan dilakukan saat TA 2021 yaitu penggantian internal part (plug dan seat ring)', NULL, 'pv-1103 leaksthroughketika trial menutup bv manual u/s pv1103, suara passing menghilangketika bv dibuka kembali, suara passing muncul kembali', NULL, 'Close', '2020-05-27 00:00:00', '2020-06-01 10:50:41', '2020-07-28 14:47:07', '2020-06-08 09:59:05', '2020-06-08 11:11:38', NULL, NULL, NULL, '2020-05-28 07:12:30', '2020-10-20 18:51:34', NULL, 150, 96, 4, 4, 2, 3, 8, 6, 168, 62, NULL, 2, 1, 1),
	(110, 'LI-0620-0001', 'WR23912, Switch PM-0301A to PM-0301C untuk pengecekan PM-0301A', 'PM-0301A', 'Sudah dilakukan pembersihan motor, dan penggatian labirynth. masih ada bocoran kecil dan perlu dilakukan monitoring bocoran oli. Dari TSP sudah dikeluarkan rekomendasi, dan perlu dilakukan overhaul kembali pada saat TA nanti.', 'Perlu dilakukan study lebih lanjut oleh TSP', 'oli motor pm-0301a rembes dari body samping', NULL, 'Close', '2020-06-02 00:00:00', '2020-06-05 13:41:15', '2020-06-30 07:57:37', '2020-06-08 09:58:07', '2020-06-08 11:13:39', NULL, 15641, 17205.10, '2020-06-02 08:14:08', '2021-03-07 22:35:59', NULL, 150, 96, 4, 4, 2, 2, 3, 6, 168, 83, NULL, 1, 1, 1),
	(111, 'LI-0620-0002', 'WR23930', 'FT-9501', 'FT-9501 rusak dan perlu dilakukan penggantian dengan unit yang baru.', 'Rusak karena normal ware, dan perlu penggantian baru. Rekomendasi dari TSP sudah dikeluarkan sehubungan dengan spec unit baru.', 'ketika proses pengapalan ft9501 tidak nunjuk', NULL, 'Close', '2020-06-07 11:18:31', '2020-06-11 13:51:10', '2020-06-30 07:57:03', '2020-06-08 09:59:33', '2020-06-08 11:14:03', NULL, 1500, 6750.00, '2020-06-06 23:04:54', '2021-03-07 22:42:07', NULL, 150, 96, 4, 4, 2, 2, 3, 6, 168, 83, NULL, 2, 1, 2),
	(112, 'LI-0620-0003', 'adjust damper manual', 'H-1101', 'Pengecekan pada damper ditemukan ada bagian-bagian yang menyebabkan damper macet. Perbaikan damper dilakukan oleh tim Maintenance - Mechanic', 'Perlu dilakukan review RCM oleh TSP', 'temuan start up 17 mei 2020damper pkb tidak bekerja normal - mengikuti acc', NULL, 'Close', '2020-05-17 20:00:08', '2020-09-06 02:00:00', '2020-06-30 07:56:31', '2020-06-08 09:59:49', '2020-06-08 11:14:28', NULL, 856, 3852.00, '2020-06-06 23:07:20', '2021-03-07 22:43:37', NULL, 150, 96, 4, 4, 2, 3, 3, 6, 168, 83, NULL, 2, 1, 2),
	(113, 'LI-0620-0004', 'Pengosongan menggunakan sump pump', 'FT-2105', 'Grating telah diperbaiki dan selesai tanggal 15 Juli 2020', NULL, 'ft-2105 (flowmeter outfall) terendam air karena air masuk dari sisi parit. parit dalam kondisi hampir penuh dan air masuk melalui jalur kabel untuk transmitter. dikhawatirkan internal part ft rusak', NULL, 'Close', '2020-06-09 15:32:51', '2020-07-15 07:01:53', '2020-07-13 09:32:57', '2020-07-10 15:00:19', '2020-07-10 15:05:07', NULL, NULL, NULL, '2020-06-08 07:34:57', '2020-07-25 23:03:14', NULL, 124, 120, 7, 2, 2, 2, 3, 6, 135, 167, NULL, 2, 1, NULL),
	(114, 'LI-0620-0005', NULL, 'PM-2103C', 'Cleaning and repair (See attachment)', 'Review task and install canopy (See attachment)', 'temuaan saat melakukan preventive maintenance nilai tahanan insulasi untuk motor pm-2103c kecil (14 mega ohm di 30 sec) (14.9 mega ohm di 1 menit) dan (88.2 mega ohm di 10 menit)', NULL, 'Close', '2020-06-16 14:26:07', '2020-08-10 09:00:21', '2020-07-28 14:47:33', '2020-06-29 10:05:22', '2020-07-16 08:33:21', NULL, 277, 1246.50, '2020-06-17 05:53:58', '2021-03-07 22:54:44', NULL, 84, 83, 3, 4, 2, 4, 8, 6, 169, 62, NULL, 2, 1, NULL),
	(115, 'LI-0620-0006', NULL, 'PM-2301C', 'Cleaning and repair (See attachment)', 'Review task and install canopy (See attachment)', 'temuaan saat melakukan preventive maintenance nilai tahanan insulasi untuk motor pm-2301c kecil (7 mega ohm di 30 sec) (17 mega ohm di 1 menit) dan (44.5 mega ohm di 10 menit)', NULL, 'Close', '2020-06-16 13:54:20', '2020-08-10 08:56:38', '2020-07-28 14:47:55', '2020-06-29 10:05:11', '2020-07-16 08:32:12', NULL, NULL, NULL, '2020-06-17 05:55:53', '2020-10-20 16:01:28', NULL, 84, 83, 3, 4, 2, 4, 8, 6, 169, 62, NULL, 2, 1, NULL),
	(116, 'LI-0620-0007', 'Simulasi open/close ZV-9502, Restart pompa KNI', 'ZV-9502', 'Dari pengecekan pada solenoid valve, ditemukan terminal ada tanda-tanda korosi. Setelah itu solenoid diganti dengan yang baru.', 'Perlu dilakukan review terhadap RCM oleh TSP', '12 jun 2020, sekitar pukul 00:30 radio komando kni menginfokan flow transfer kni dari kpi dropdilakukan pengecekan, pompa transfer kpi masih kontinyu running,kemudian ditemukan zv-9502 close(tidak ada alarm di dcs)', NULL, 'Close', '2020-06-22 00:37:00', '2020-08-12 15:00:00', '2020-07-22 11:09:49', '2020-07-01 14:39:00', '2020-07-22 09:53:21', NULL, 2520, 11340.00, '2020-06-21 08:27:33', '2021-03-07 22:41:02', NULL, 150, 163, 4, 4, 2, 2, 3, 6, 168, 83, NULL, 2, 1, 2),
